with open('index.html') as f:
    content = f.read()

changes = 0

old_css = "  .auth-gate{\n    position:fixed; inset:0; z-index:200; display:none;\n    background:var(--ink); color:#f2efe6;\n    align-items:center; justify-content:center; flex-direction:column; gap:28px;\n    padding:24px;\n  }\n  .auth-card{\n    background:#1e2938; border:1px solid #303e50; border-radius:14px;\n    padding:36px 34px; width:100%; max-width:360px; box-shadow:0 20px 60px rgba(0,0,0,.35);\n  }\n  .auth-brand{display:flex; align-items:baseline; gap:10px; margin-bottom:6px;}\n  .auth-brand h1{font-size:16px; font-weight:600; margin:0;}\n  .auth-sub{color:#9aa4ae; font-size:12.5px; font-family:'IBM Plex Mono'; margin-bottom:24px;}\n  .auth-graphic{display:block; margin:0 auto 26px auto; width:100%; max-width:260px;}\n  .auth-field{margin-bottom:14px;}\n  .auth-field label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:#9aa4ae; display:block; margin-bottom:6px;}\n  .auth-field input{\n    width:100%; padding:10px 12px; border-radius:6px; border:1px solid #3a4658;\n    background:#141c27; color:#f2efe6; font-size:14px; font-family:'IBM Plex Sans';\n  }\n  .auth-field input:focus{outline:2px solid var(--amber); outline-offset:0; border-color:var(--amber);}\n  .auth-submit{\n    width:100%; margin-top:6px; background:var(--amber); color:#412402; border:none;\n    font-weight:600; font-size:14px; padding:11px; border-radius:6px; cursor:pointer;\n  }\n  .auth-submit:hover{background:#dca03e;}\n  .auth-submit:disabled{opacity:.6; cursor:not-allowed;}\n  .auth-error{\n    margin-top:12px; font-size:12.5px; color:#ffb4a8; background:rgba(232,89,60,.12);\n    border:1px solid rgba(232,89,60,.35); padding:8px 10px; border-radius:6px;\n  }\n"
new_css = "  .auth-gate{\n    position:fixed; inset:0; z-index:200; display:none;\n    background:radial-gradient(ellipse at top left, #16212f 0%, #0b1420 55%), var(--ink);\n    color:#f2efe6; overflow:hidden;\n    align-items:center; justify-content:center; flex-direction:column;\n    padding:24px;\n  }\n  .auth-bg{position:absolute; inset:0; z-index:0; overflow:hidden;}\n  .auth-glow{position:absolute; border-radius:50%; filter:blur(90px); opacity:.32; animation:authDrift 16s ease-in-out infinite;}\n  .auth-glow-amber{width:440px; height:440px; background:#EF9F27; top:-140px; left:-100px;}\n  .auth-glow-teal{width:520px; height:520px; background:#1D9E75; bottom:-160px; right:-120px; animation-delay:-7s; animation-duration:19s;}\n  @keyframes authDrift{0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(36px,-26px) scale(1.06);}}\n\n  .auth-flow{position:absolute; inset:0; width:100%; height:100%; z-index:1;}\n  .flow-path{fill:none; stroke-width:1.4; stroke-dasharray:9 9; animation:flowMove 7s linear infinite;}\n  .flow-path-a{stroke:rgba(29,158,117,.4); animation-duration:7s;}\n  .flow-path-b{stroke:rgba(239,159,39,.32); animation-duration:9.5s; animation-direction:reverse;}\n  .flow-path-c{stroke:rgba(29,158,117,.24); animation-duration:12s;}\n  @keyframes flowMove{to{stroke-dashoffset:-180;}}\n  .flow-dot{animation:travel linear infinite;}\n  @keyframes travel{from{offset-distance:0%; opacity:0;} 5%{opacity:1;} 95%{opacity:1;} to{offset-distance:100%; opacity:0;}}\n  @media (prefers-reduced-motion: reduce){\n    .auth-glow, .flow-path, .flow-dot{animation:none;}\n  }\n\n  .auth-card{\n    position:relative; z-index:2;\n    background:rgba(28,38,51,.82); backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px);\n    border:1px solid rgba(255,255,255,.08); border-radius:16px;\n    padding:40px 36px; width:100%; max-width:380px;\n    box-shadow:0 24px 70px rgba(0,0,0,.45), 0 0 0 1px rgba(255,255,255,.02) inset;\n    animation:authCardIn .55s cubic-bezier(.16,1,.3,1);\n  }\n  @keyframes authCardIn{from{opacity:0; transform:translateY(16px) scale(.98);} to{opacity:1; transform:translateY(0) scale(1);}}\n  .auth-brand{display:flex; align-items:center; gap:10px; margin-bottom:4px;}\n  .auth-brand h1{font-size:17px; font-weight:600; margin:0;}\n  .auth-sub{color:#9aa4ae; font-size:12.5px; font-family:'IBM Plex Mono'; margin-bottom:26px;}\n  .auth-field{margin-bottom:14px;}\n  .auth-field label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:#9aa4ae; display:block; margin-bottom:6px;}\n  .auth-field input{\n    width:100%; padding:10px 12px; border-radius:6px; border:1px solid #3a4658;\n    background:rgba(20,28,39,.8); color:#f2efe6; font-size:14px; font-family:'IBM Plex Sans';\n    transition:border-color .15s, background .15s;\n  }\n  .auth-field input:focus{outline:2px solid var(--amber); outline-offset:0; border-color:var(--amber); background:#141c27;}\n  .auth-submit{\n    width:100%; margin-top:6px; background:var(--amber); color:#412402; border:none;\n    font-weight:600; font-size:14px; padding:11px; border-radius:6px; cursor:pointer;\n    transition:background .15s, transform .1s;\n  }\n  .auth-submit:hover{background:#dca03e;}\n  .auth-submit:active{transform:scale(.98);}\n  .auth-submit:disabled{opacity:.6; cursor:not-allowed;}\n  .auth-error{\n    margin-top:12px; font-size:12.5px; color:#ffb4a8; background:rgba(232,89,60,.12);\n    border:1px solid rgba(232,89,60,.35); padding:8px 10px; border-radius:6px;\n  }\n"
if old_css in content:
    content = content.replace(old_css, new_css, 1)
    changes += 1

old_div = '<div class="auth-gate" id="authGate">\n  <div class="auth-card">\n    <svg class="auth-graphic" viewBox="0 0 260 130" fill="none" xmlns="http://www.w3.org/2000/svg">\n      <path d="M18,96 Q75,34 132,74 T244,36" stroke="#1D9E75" stroke-width="3" stroke-dasharray="7 7" fill="none"/>\n      <circle cx="18" cy="96" r="6" fill="#EF9F27"/>\n      <circle cx="132" cy="74" r="6" fill="#EF9F27"/>\n      <circle cx="244" cy="36" r="12" fill="#1D9E75"/>\n      <path d="M238,36 l4,5 l9,-11" stroke="#0B1420" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>\n      <rect x="8" y="106" width="26" height="18" rx="3" fill="#2A3546"/>\n      <line x1="13" y1="112" x2="29" y2="112" stroke="#5C6B80" stroke-width="1.5"/>\n      <line x1="13" y1="117" x2="24" y2="117" stroke="#5C6B80" stroke-width="1.5"/>\n    </svg>\n    <div class="auth-brand">\n      <span class="mark"></span>\n      <h1>Shree Radhe Enterprises</h1>\n    </div>\n    <div class="auth-sub">Sign in to the ledger</div>\n    <form id="loginForm">\n      <div class="auth-field">\n        <label>Email</label>\n        <input type="email" id="loginEmail" autocomplete="username" required>\n      </div>\n      <div class="auth-field">\n        <label>Password</label>\n        <input type="password" id="loginPassword" autocomplete="current-password" required>\n      </div>\n      <button type="submit" class="auth-submit">Sign in</button>\n      <div class="auth-error" id="loginError" hidden></div>\n    </form>\n  </div>\n</div>'
new_div = '<div class="auth-gate" id="authGate">\n  <div class="auth-bg" aria-hidden="true">\n    <div class="auth-glow auth-glow-amber"></div>\n    <div class="auth-glow auth-glow-teal"></div>\n    <svg class="auth-flow" viewBox="0 0 800 600" preserveAspectRatio="xMidYMid slice">\n      <path class="flow-path flow-path-a" d="M-50,430 C150,360 300,480 500,360 S760,290 900,340"/>\n      <path class="flow-path flow-path-b" d="M-50,170 C200,250 350,110 550,210 S800,140 900,170"/>\n      <path class="flow-path flow-path-c" d="M-50,300 C180,240 400,340 600,260 S850,200 900,240"/>\n      <circle class="flow-dot" r="4" fill="#EF9F27" style="offset-path:path(\'M-50,430 C150,360 300,480 500,360 S760,290 900,340\'); animation-duration:6.5s;"/>\n      <circle class="flow-dot" r="4" fill="#1D9E75" style="offset-path:path(\'M-50,170 C200,250 350,110 550,210 S800,140 900,170\'); animation-duration:8.5s; animation-delay:-2s;"/>\n      <circle class="flow-dot" r="3.5" fill="#EF9F27" style="offset-path:path(\'M-50,300 C180,240 400,340 600,260 S850,200 900,240\'); animation-duration:10.5s; animation-delay:-5s;"/>\n      <circle class="flow-dot" r="4" fill="#1D9E75" style="offset-path:path(\'M-50,430 C150,360 300,480 500,360 S760,290 900,340\'); animation-duration:6.5s; animation-delay:-3.2s;"/>\n      <circle class="flow-dot" r="3.5" fill="#1D9E75" style="offset-path:path(\'M-50,170 C200,250 350,110 550,210 S800,140 900,170\'); animation-duration:8.5s; animation-delay:-6s;"/>\n    </svg>\n  </div>\n  <div class="auth-card">\n    <div class="auth-brand">\n      <span class="mark"></span>\n      <h1>Shree Radhe Enterprises</h1>\n    </div>\n    <div class="auth-sub">Sign in to the ledger</div>\n    <form id="loginForm">\n      <div class="auth-field">\n        <label>Email</label>\n        <input type="email" id="loginEmail" autocomplete="username" required>\n      </div>\n      <div class="auth-field">\n        <label>Password</label>\n        <input type="password" id="loginPassword" autocomplete="current-password" required>\n      </div>\n      <button type="submit" class="auth-submit">Sign in</button>\n      <div class="auth-error" id="loginError" hidden></div>\n    </form>\n  </div>\n</div>'
if old_div in content:
    content = content.replace(old_div, new_div, 1)
    changes += 1

if changes == 2:
    with open('index.html', 'w') as f:
        f.write(content)
    print("SUCCESS: login page upgraded.")
elif changes == 0:
    print("NOTHING MATCHED: your file may already be upgraded, or differs from expected.")
else:
    print(f"PARTIAL: only {changes} of 2 patches applied -- file NOT saved. Send this output back.")
